import { WorkspaceSessionRenewal, validateWorkspaceSessionEnvelope } from './workspace-renewal.mjs';
import { formatArea, formatGsd } from './unit-formatters.mjs';

const TOKEN_KEY='ltds-viewer-admin-token';
const NAV=[['dashboard','⌂','Dashboard'],['providers','⌁','Providers & nodes'],['diagnostics','▤','Diagnostics']];
const ACTIVE=new Set(['pending','admitted','initializing','uploading','committed','queued_upstream','running','ingesting','derivatives']);
const state={section:'dashboard',token:sessionStorage.getItem(TOKEN_KEY),adminSession:null,projects:[],datasets:[],tasks:[],providers:[],presets:[],outputs:[],shares:{},projectShares:{},clientAccess:null,lastShareUrl:null,storage:null,failedMutations:[],ready:null,busy:false,projectQuery:'',selectedProjectId:null,expandedTaskId:null,selectedProviderId:null,taskDetails:{},gcpWorkspaces:{},logTimer:null};
const content=document.querySelector('#workspace-content'),shell=document.querySelector('#workspace'),modal=document.querySelector('#workspace-modal'),modalContent=document.querySelector('#workspace-modal-content');
const workspaceController=window.opener&&!window.opener.closed?window.opener:null;
let workspaceRenewal=null;

async function openShareModal(projectId,onlyOutputId=null){if(can('viewer.shares.read')||can('viewer.shares.revoke')){try{state.projectShares[projectId]=(await api(`/api/v1/projects/${encodeURIComponent(projectId)}/public-shares`)).shares||[]}catch(error){if(error.status===401)return;state.projectShares[projectId]=[]}}shareModal(projectId,onlyOutputId);injectProjectShareCard(projectId)}
function injectProjectShareCard(projectId){
  const mayCreate=can('viewer.shares.create'),mayRead=can('viewer.shares.read'),mayRevoke=can('viewer.shares.revoke');
  if(!mayCreate&&!mayRead&&!mayRevoke)return;
  const taskIds=new Set(state.tasks.filter(task=>task.projectId===projectId).map(task=>task.id)),published=state.outputs.filter(output=>output.activePublished&&taskIds.has(output.taskId)),shares=state.projectShares[projectId]||[],target=modalContent.querySelector('.share-columns > div:last-child');
  if(!target)return;
  const create=mayCreate?(published.length?`<form class="manage-form project-share-form" data-project-id="${esc(projectId)}">${field('Link label','label','maxlength="120"')}${field('Optional password','password','type="password" minlength="8" autocomplete="new-password"')}${field('Expiry','expiresAt','type="datetime-local"')}<label class="check"><input type="checkbox" name="measure" checked> Measurements</label><label class="check"><input type="checkbox" name="cameras" checked> Camera positions</label><label class="check"><input type="checkbox" name="download"> Show download controls</label><button class="primary-button">Create whole-project link</button><p class="form-note">This link always shows the project's current published tasks, including tasks published later.</p></form>`:empty('Publish at least one task before creating a whole-project link.')):'';
  const list=mayRead||mayRevoke?`<div class="data-list top-gap">${shares.map(share=>`<div class="manage-row"><div><strong>${esc(share.label||'Whole-project link')}</strong><small>${share.hasPassword?'Password protected':'No password'} · ${share.accessCount||0} views</small></div>${badge(share.revokedAt?'revoked':'active')}<div>${!share.revokedAt&&mayRevoke?button('revoke-project-share',share.id,'Revoke'):''}</div></div>`).join('')||empty('No whole-project public links.')}</div>`:'';
  target.insertAdjacentHTML('afterbegin',card('Whole-project public link',create+list));
  bindProjectShareCard(projectId);
}
function bindProjectShareCard(projectId){const form=modalContent.querySelector('.project-share-form');if(form)form.onsubmit=async event=>{event.preventDefault();const input=values(form),body={label:input.label,expiresAt:input.expiresAt?new Date(input.expiresAt).toISOString():null,permissions:{view:true,measure:form.elements.measure.checked,cameras:form.elements.cameras.checked,download:form.elements.download.checked}};if(input.password)body.password=input.password;try{const result=await api(`/api/v1/projects/${encodeURIComponent(projectId)}/public-shares`,{method:'POST',body});state.lastShareUrl=result.viewUrl;await navigator.clipboard?.writeText(result.viewUrl);toast('Whole-project link created and copied');await openShareModal(projectId)}catch(error){toast(error.message,true)}};modalContent.querySelectorAll('[data-action="revoke-project-share"]').forEach(element=>element.onclick=()=>{modal.close();mutate(`/api/v1/project-shares/${encodeURIComponent(element.dataset.id)}`,{method:'DELETE',body:{}},'Whole-project link revoked')})}

const esc=value=>String(value??'').replace(/[&<>"']/g,character=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[character]));
const badge=value=>`<span class="status ${esc(value)}">${esc(String(value||'unknown').replaceAll('_',' '))}</span>`;
const bytes=value=>{const number=Number(value);if(!Number.isFinite(number))return'Unavailable';if(!number)return'0 B';const units=['B','KB','MB','GB','TB'],index=Math.min(Math.floor(Math.log(number)/Math.log(1024)),4);return`${(number/1024**index).toFixed(index>1?1:0)} ${units[index]}`};
const dateTime=value=>value?new Date(value).toLocaleString():'Unavailable';
const duration=attempt=>{const start=Date.parse(attempt?.startedAt||attempt?.createdAt||''),end=Date.parse(attempt?.completedAt||attempt?.updatedAt||'');if(!Number.isFinite(start)||!Number.isFinite(end)||end<start)return'Unavailable';const total=Math.round((end-start)/1000),hours=Math.floor(total/3600),minutes=Math.floor(total%3600/60);return hours?`${hours}h ${minutes}m`:`${minutes}m ${total%60}s`};
const available=value=>value===undefined||value===null||value===''?'Unavailable':esc(value);
const opts=(items,label='Select')=>`<option value="">${esc(label)}</option>${items.map(item=>`<option value="${esc(item.id)}">${esc(item.displayName||item.name||item.id)}</option>`).join('')}`;
const empty=message=>`<div class="empty-state">${esc(message)}</div>`;
const field=(label,name,attributes='')=>`<label><span>${esc(label)}</span><input name="${esc(name)}" ${attributes}></label>`;
const select=(label,name,options)=>`<label><span>${esc(label)}</span><select name="${esc(name)}" required>${options}</select></label>`;
const button=(action,id,label,primary=false,extra='')=>`<button class="${primary?'primary':'secondary'}-button" data-action="${esc(action)}" data-id="${esc(id)}" ${extra}>${esc(label)}</button>`;
const dangerButton=(action,id,label,extra='')=>`<button class="secondary-button danger-button" data-action="${esc(action)}" data-id="${esc(id)}" ${extra}>${esc(label)}</button>`;
const card=(title,body,action='')=>`<article class="content-card"><div class="card-heading"><h2>${esc(title)}</h2>${action}</div>${body}</article>`;
const values=form=>Object.fromEntries(new FormData(form).entries());
const safeFileName=value=>String(value||'processing-output').replace(/[\\/:*?"<>|\u0000-\u001f]/g,'-').slice(0,160)||'processing-output';
const can=permission=>Boolean(state.adminSession?.permissions?.includes(permission));

function toast(message,bad=false){const element=document.querySelector('#workspace-toast');element.textContent=message;element.className=bad?'bad':'';element.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>element.style.display='none',4000)}
function responseError(message,status){const error=Error(message);error.status=status;return error}
function clearWorkspaceAuthorization(){workspaceRenewal?.dispose();workspaceRenewal=null;releaseAllGcpImages();sessionStorage.removeItem(TOKEN_KEY);state.token=null;state.adminSession=null;clearInterval(state.logTimer);renderNav();access()}
async function api(path,{method='GET',body,headers={}}={}){const init={method,headers:{Authorization:`Bearer ${state.token}`,Accept:'application/json',...headers}};if(method!=='GET'&&!init.headers['Idempotency-Key'])init.headers['Idempotency-Key']=crypto.randomUUID();if(body!==undefined){init.headers['Content-Type']='application/json';init.body=JSON.stringify(body)}const response=await fetch(path,init);let payload;try{payload=await response.json()}catch{}if(response.status===401){clearWorkspaceAuthorization();throw responseError('authorization_required',401)}if(response.status===403)throw responseError('Your current Viewer grant does not permit this action',403);if(!response.ok)throw responseError(payload?.message||payload?.error||`Request failed (${response.status})`,response.status);return payload}
async function authenticatedDownload(path,fileName){const response=await fetch(path,{headers:{Authorization:`Bearer ${state.token}`}});if(response.status===401){clearWorkspaceAuthorization();throw responseError('authorization_required',401)}if(response.status===403)throw responseError('Your current Viewer grant does not permit this download',403);if(!response.ok)throw responseError(`Download failed (${response.status})`,response.status);const blob=await response.blob(),url=URL.createObjectURL(blob),link=document.createElement('a');try{link.href=url;link.download=fileName;document.body.append(link);link.click()}finally{link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}}
async function mutate(path,options,message){if(state.busy)return;state.busy=true;shell.setAttribute('aria-busy','true');try{const result=await api(path,options);toast(message);await load();return result}catch(error){toast(error.message,true)}finally{state.busy=false;shell.removeAttribute('aria-busy')}}
async function confirmedMutation(promptText,path,options,message){if(!confirm(promptText))return;return mutate(path,options,message)}
function installWorkspaceSession(envelope){const checked=validateWorkspaceSessionEnvelope({...envelope,accessToken:envelope.accessToken||state.token});if(envelope.accessToken){state.token=envelope.accessToken;sessionStorage.setItem(TOKEN_KEY,state.token)}state.adminSession=checked.session;workspaceRenewal?.dispose();workspaceRenewal=new WorkspaceSessionRenewal({controllerWindow:workspaceController,envelope,accessToken:state.token,onSession:value=>{state.adminSession=value.session},onExpired:clearWorkspaceAuthorization});workspaceRenewal.start()}
async function redeemGrant(){const parts=location.pathname.split('/').filter(Boolean),grant=parts[0]==='workspace'&&parts[1]&&parts[1]!=='active'?decodeURIComponent(parts[1]):null;if(!grant)return false;const response=await fetch('/api/v1/admin-sessions/redeem',{method:'POST',headers:{'Content-Type':'application/json',...(state.token?{Authorization:`Bearer ${state.token}`}:{})},body:JSON.stringify({grant})});let body;try{body=await response.json()}catch{body={}}if(response.status===401){clearWorkspaceAuthorization();throw responseError('authorization_required',401)}if(!response.ok)throw responseError(body.error||`Grant redemption failed (${response.status})`,response.status);installWorkspaceSession(body);history.replaceState(null,'','/workspace');return true}
async function restoreWorkspaceSession(){if(!state.token)return false;const response=await fetch('/api/v1/admin-sessions/current',{headers:{Authorization:`Bearer ${state.token}`,Accept:'application/json'}});let body;try{body=await response.json()}catch{body={}}if(response.status===401){clearWorkspaceAuthorization();throw responseError('authorization_required',401)}if(!response.ok)throw responseError(body.error||`Session check failed (${response.status})`,response.status);installWorkspaceSession(body);return true}

function renderNav(){document.querySelector('#workspace-navigation').innerHTML=NAV.map(([id,icon,label])=>`<button class="nav-link ${state.section===id?'active':''}" data-section="${id}"><span class="nav-icon">${icon}</span>${label}</button>`).join('');document.querySelectorAll('.nav-link').forEach(link=>link.onclick=()=>{state.section=link.dataset.section;shell.classList.remove('nav-open');render()})}
function metric(label,value,description){return`<article class="metric-card"><p>${esc(label)}</p><strong>${available(value)}</strong><small>${esc(description)}</small></article>`}
function openModal(title,body,className=''){modal.className=`workspace-modal ${className}`;modalContent.innerHTML=`<div class="modal-heading"><div><p class="eyebrow">Viewer workspace</p><h2 id="workspace-modal-title">${esc(title)}</h2></div><button class="icon-button modal-close" aria-label="Close dialog">×</button></div>${body}`;modalContent.querySelector('.modal-close').onclick=()=>modal.close();modal.showModal()}

function dashboard(){const active=state.tasks.filter(task=>ACTIVE.has(task.latestAttempt?.status)).length,healthy=state.providers.filter(provider=>provider.enabled&&['healthy','ready'].includes(provider.runtimeHealth||provider.lastHealth)).length;return`<div class="metric-grid">${metric('Projects',state.projects.length,'Viewer projects')}${metric('Published outputs',state.outputs.filter(output=>output.status==='published').length,bytes(state.outputs.reduce((sum,output)=>sum+(+output.byteSize||0),0)))}${metric('Processing now',active,'Active pipeline work')}${metric('Provider nodes',`${healthy}/${state.providers.length}`,'Enabled and healthy')}</div><section class="project-workspace top-gap"><div class="project-toolbar"><label class="project-search"><span class="sr-only">Filter projects by name</span><input id="project-filter" type="search" value="${esc(state.projectQuery)}" placeholder="Search projects…" autocomplete="off"></label><button class="primary-button" data-action="new-project">New project</button></div><div id="project-list" class="project-list">${projectRows()}</div>${selectedProject()}</section>`}
function projectRows(){const query=state.projectQuery.trim().toLocaleLowerCase('en-US'),projects=state.projects.filter(project=>!query||project.displayName.toLocaleLowerCase('en-US').includes(query));if(!projects.length)return empty(query?'No projects match that name.':'No projects yet.');return projects.map(project=>{const tasks=state.tasks.filter(task=>task.projectId===project.id),datasets=state.datasets.filter(dataset=>dataset.projectId===project.id),running=tasks.filter(task=>ACTIVE.has(task.latestAttempt?.status)).length,published=tasks.filter(task=>task.status==='published').length,selected=project.id===state.selectedProjectId;return`<article class="project-row ${selected?'selected':''}" data-project-name="${esc(project.displayName.toLocaleLowerCase('en-US'))}"><button class="project-open" data-action="open-project" data-id="${esc(project.id)}" aria-expanded="${selected}"><span><strong>${esc(project.displayName)}</strong><small>${esc(project.description||'No description')}</small></span><span class="project-stat"><strong>${tasks.length}</strong><small>tasks</small></span><span class="project-stat"><strong>${running}</strong><small>running</small></span><span class="project-stat"><strong>${published}</strong><small>published</small></span><span class="project-stat"><strong>${datasets.length}</strong><small>datasets</small></span>${badge(project.status)}<span aria-hidden="true">›</span></button></article>`}).join('')}
function selectedProject(){
  const project=state.projects.find(item=>item.id===state.selectedProjectId);if(!project)return'';
  const tasks=state.tasks.filter(task=>task.projectId===project.id),datasets=state.datasets.filter(dataset=>dataset.projectId===project.id),readyDatasets=datasets.filter(dataset=>dataset.status==='finalized'),active=project.status==='active',hasActiveTask=tasks.some(task=>ACTIVE.has(task.latestAttempt?.status)||['queued','processing'].includes(task.status)),canShare=['viewer.shares.create','viewer.shares.read','viewer.shares.revoke','viewer.client_grants.manage'].some(can);
  const actions=active?`${can('viewer.datasets.import')?button('project-import',project.id,'Import'):''}${can('viewer.processing.write')?`<button class="primary-button" data-action="project-process" data-id="${esc(project.id)}" ${readyDatasets.length&&state.providers.some(provider=>provider.enabled)?'':'disabled'}>New task</button>`:''}${canShare?button('project-share',project.id,'Share'):''}${can('viewer.projects.write')&&!hasActiveTask?dangerButton('archive-project',project.id,'Archive'):''}`:'';
  const datasetForm=active&&can('viewer.datasets.write')?`<form id="dataset-form" class="manage-form inline-form"><input type="hidden" name="projectId" value="${esc(project.id)}">${field('Dataset name','displayName','required maxlength="240"')}<button class="secondary-button">Create upload draft</button></form>`:'';
  const datasetRows=datasets.map(dataset=>`<div class="manage-row"><div><strong>${esc(dataset.displayName)}</strong><small>${dataset.fileCount??0} files · ${bytes(dataset.byteSize)}</small></div>${badge(dataset.status)}<div class="row-actions">${datasetActions(dataset,active)}</div></div>`).join('')||empty('No datasets yet.');
  return`<section class="project-detail" aria-label="${esc(project.displayName)} project"><div class="project-detail-heading"><div><button class="text-button" data-action="close-project">← All projects</button><p class="eyebrow">Project</p><h2>${esc(project.displayName)}</h2><p>${esc(project.description||'No project description.')}</p>${active?'':'<p class="form-note">This project is archived and read-only.</p>'}</div><div class="row-actions">${actions}</div></div><div class="project-columns">${card('Tasks',`<div class="task-list">${tasks.map(taskPanel).join('')||empty('No tasks in this project yet.')}</div>`)}${card('Project datasets',`${datasetForm}<div class="data-list ${datasetForm?'top-gap':''}">${datasetRows}</div>`)}</div></section>`;
}
function datasetActions(dataset,projectActive){if(!projectActive)return'';const items=[];if(dataset.status==='draft'&&can('viewer.datasets.write'))items.push(button('upload-dataset',dataset.id,'Upload'));if(dataset.status==='finalized'&&can('viewer.datasets.write'))items.push(button('archive-dataset',dataset.id,'Archive'));if(['draft','finalized','archived'].includes(dataset.status)&&can('viewer.storage.purge'))items.push(dangerButton('trash-dataset',dataset.id,'Move to trash'));return items.join('')}
function taskPanel(task){const attempt=task.latestAttempt||{},expanded=state.expandedTaskId===task.id,dataset=state.datasets.find(item=>item.id===task.datasetId),sourceImages=task.metrics?.sourceImageCount;return`<article class="task-panel ${expanded?'expanded':''}"><button class="task-summary" data-action="toggle-task" data-id="${esc(task.id)}" aria-expanded="${expanded}"><span class="task-chevron" aria-hidden="true">${expanded?'⌄':'›'}</span><span><strong>${esc(task.displayName)}</strong><small>${dateTime(task.createdAt)}</small></span><span class="task-summary-stat"><strong>${sourceImages??'—'}</strong><small>images</small></span><span class="task-summary-stat"><strong>${duration(attempt)}</strong><small>runtime</small></span>${badge(attempt.status||task.status)}</button>${expanded?taskDetail(task,dataset):''}</article>`}
function metricItem(label,value,unit=''){return`<div class="task-metric"><span>${esc(label)}</span><strong>${available(value)}${value===undefined||value===null||value===''?'':esc(unit)}</strong></div>`}
function taskDetail(task,dataset){const detail=state.taskDetails[task.id],attempt=detail?.attempt||task.latestAttempt||{},metrics=detail?.task?.metrics||task.metrics||{},storage=detail?.storage?.task,outputs=detail?.task?.outputs||state.outputs.filter(output=>output.taskId===task.id),units=state.adminSession?.displayUnits||'imperial',projectActive=state.projects.find(project=>project.id===task.projectId)?.status==='active',readOnly=task.status==='archived'||!projectActive;if(detail?.loading)return`<div class="task-detail">${empty('Loading authoritative task details…')}</div>`;const controls=readOnly?`<p class="form-note">This ${task.status==='archived'?'task':'project'} is archived and read-only.</p>`:`<div class="row-actions task-lifecycle">${can('viewer.processing.write')?`${button('edit-task',task.id,'Edit')}${activeTaskAction(task,attempt)}${!ACTIVE.has(attempt.status)?dangerButton('archive-task',task.id,'Archive task'):''}`:''}</div>`;return`<div class="task-detail"><div class="task-detail-grid"><section><h3>Processing summary</h3><div class="task-metrics">${metricItem('Average GSD',metrics.averageGsdM==null?null:formatGsd(metrics.averageGsdM,units))}${metricItem('Surveyed area',metrics.surveyedAreaM2==null?null:formatArea(metrics.surveyedAreaM2,units))}${metricItem('Source images',metrics.sourceImageCount)}${metricItem('Reconstructed points',metrics.reconstructedPointCount)}${metricItem('Georeferencing CRS',metrics.georeferencingCrs)}${metricItem('Processing duration',metrics.processingDurationMs==null?duration(attempt):durationFromMs(metrics.processingDurationMs))}${metricItem('Output availability',metrics.outputCount?`${metrics.outputCount} output${metrics.outputCount===1?'':'s'}`:null)}${metricItem('Task disk usage',metrics.taskDiskUsageBytes==null?(storage?.totalBytes===undefined?null:bytes(storage.totalBytes)):bytes(metrics.taskDiskUsageBytes))}</div><p class="form-note">Unavailable means the processing API did not provide an authoritative value.</p></section><section><h3>Task controls</h3><dl class="task-options"><div><dt>Dataset</dt><dd>${esc(dataset?.displayName||'Unavailable')}</dd></div><div><dt>Provider</dt><dd>${esc(state.providers.find(provider=>provider.id===attempt.providerId)?.displayName||'Unavailable')}</dd></div><div><dt>Preset</dt><dd>${esc(state.presets.find(preset=>preset.id===attempt.presetId)?.displayName||'Provider defaults')}</dd></div><div><dt>Status</dt><dd>${badge(metrics.processingStatus||attempt.status||task.status)}</dd></div></dl>${controls}</section></div>${attemptHistory(detail?.attempts||[],attempt.id,!readOnly)}${readOnly?'<section class="task-subsection"><p class="form-note">GCP and processing changes are unavailable for archived work.</p></section>':gcpPanel(task,dataset,detail?.gcp||{sets:[]})}${outputPanel(task,attempt,outputs,!readOnly)}${logPanel(task,attempt,detail?.logs||[])}</div>`}
function attemptHistory(attempts,currentId,allowRetry=true){return`<details class="task-subsection attempt-history"><summary>Processing history (${attempts.length})</summary><div class="data-list top-gap">${attempts.map(item=>`<div class="manage-row"><div><strong>${item.id===currentId?'Current attempt':'Earlier attempt'}</strong><small>${dateTime(item.createdAt)} · ${duration(item)}</small></div>${badge(item.status)}<div class="row-actions">${allowRetry&&can('viewer.processing.write')&&['failed','cancelled'].includes(item.status)?button('retry-attempt',item.id,'Retry'):''}</div></div>`).join('')||empty('No processing attempts have been recorded.')}</div></details>`}
function durationFromMs(value){const total=Math.max(0,Math.round(Number(value)/1000)),hours=Math.floor(total/3600),minutes=Math.floor(total%3600/60);return hours?`${hours}h ${minutes}m`:`${minutes}m ${total%60}s`}
function activeTaskAction(task,attempt){if(!can('viewer.processing.write')||task.status==='archived')return'';if(ACTIVE.has(attempt.status))return button('cancel-attempt',attempt.id,'Cancel');if(['failed','cancelled'].includes(attempt.status))return button('retry-attempt',attempt.id,'Restart',true);if(attempt.providerId)return button('restart-task',task.id,'Restart',false);return''}
function gcpWorkspace(taskId){return state.gcpWorkspaces[taskId]||(state.gcpWorkspaces[taskId]={setId:null,pointId:null,mode:'auto',radiusM:100,activeImage:null,imageUrl:null,draftPixel:null,editingId:null,pointCache:{}})}
function gcpImageName(image){return String(image?.relativePath||image?.id||'Image').split('/').at(-1)}
function gcpPointName(point){return point?.label||point?.externalId||point?.id||'Unknown point'}
function gcpMarkerStyle(workspace){const image=workspace.activeImage,pixel=workspace.draftPixel;if(!image||!pixel||!Number(image.width)||!Number(image.height))return'';return`left:${Math.max(0,Math.min(100,pixel.pixelX/image.width*100))}%;top:${Math.max(0,Math.min(100,pixel.pixelY/image.height*100))}%`}
function gcpPanel(task,dataset,gcp){const sets=gcp.sets||[],points=gcp.points||[],candidates=gcp.candidates||[],correspondences=gcp.correspondences||[],ranking=gcp.ranking,workspace=gcpWorkspace(task.id),selectedSet=sets.find(set=>set.id===workspace.setId),selectedPoint=points.find(point=>point.id===workspace.pointId),active=workspace.activeImage,activeMark=correspondences.find(mark=>mark.pointId===workspace.pointId&&mark.imageFileId===active?.id),pointById=new Map(points.map(point=>[point.id,point])),imageById=new Map(candidates.map(image=>[image.id,image]));const correspondenceRows=correspondences.slice(0,100).map(mark=>{const point=pointById.get(mark.pointId),image=imageById.get(mark.imageFileId);return`<div class="gcp-mark-row"><div><strong>${esc(gcpPointName(point))}</strong><small>${esc(gcpImageName(image||{id:mark.imageFileId}))} · x ${esc(mark.pixelX)}, y ${esc(mark.pixelY)}</small></div><div class="row-actions">${button('gcp-edit-mark',mark.id,'Edit',false,`data-task-id="${esc(task.id)}"`)}${button('gcp-delete-mark',mark.id,'Delete',false,`data-task-id="${esc(task.id)}"`)}</div></div>`}).join('');const candidateRows=candidates.map(image=>{const marked=correspondences.some(mark=>mark.pointId===workspace.pointId&&mark.imageFileId===image.id),distance=Number.isFinite(image.distanceM)?`${image.distanceM.toFixed(image.distanceM<100?1:0)} m away`:'Capture-time order';return`<button class="gcp-candidate ${active?.id===image.id?'active':''}" data-action="gcp-open-image" data-id="${esc(image.id)}" data-task-id="${esc(task.id)}" aria-pressed="${active?.id===image.id}"><span><strong>${esc(gcpImageName(image))}</strong><small>${esc(distance)}${image.width&&image.height?` · ${image.width}×${image.height}`:''}</small></span>${marked?badge('marked'):''}</button>`}).join('');return`<section class="task-subsection"><div class="subsection-heading"><div><h3>Ground control points</h3><p>Import authoritative survey points, rank nearby camera positions, and mark the visible point in each source image.</p></div><span>${sets.reduce((sum,set)=>sum+(Number(set.pointCount)||0),0)} points · ${correspondences.length} marks</span></div><details class="gcp-import-disclosure"><summary>Import another control-point set</summary><form class="manage-form gcp-import-form" data-dataset-id="${esc(dataset?.id||'')}" data-task-id="${esc(task.id)}">${field('Set name','displayName','required maxlength="160"')}<label><span>Survey file</span><input name="file" type="file" accept=".csv,.geojson,.json" required></label><label><span>Format</span><select name="format" required><option value="emlid-all-columns-v1">Emlid all-columns CSV</option><option value="generic-csv-v1">Generic CSV v1</option><option value="generic-geojson-v1">Generic GeoJSON v1</option></select></label><button class="secondary-button">Preview GCP import</button><p class="form-note">For Emlid exports, the server derives the exact coordinate system and units from CS name. Review that provenance before import; ambiguous files are rejected instead of guessed.</p></form></details>${gcp.error?`<p class="gcp-warning" role="alert">${esc(gcp.error)}</p>`:''}${sets.length?`<div class="gcp-marker-workspace"><aside class="gcp-controls"><label><span>Control-point set</span><select class="gcp-set-select" data-task-id="${esc(task.id)}">${sets.map(set=>`<option value="${esc(set.id)}" ${set.id===workspace.setId?'selected':''}>${esc(set.displayName)} (${set.pointCount})</option>`).join('')}</select></label>${selectedSet?`<p class="gcp-provenance"><strong>${esc(selectedSet.crs||'CRS unavailable')}</strong><span>${esc(selectedSet.provenance?.coordinateSystem||selectedSet.crs||'Coordinate system unavailable')}</span><span>${esc(selectedSet.provenance?.verticalDatum||'Vertical datum unavailable')} · ${esc(selectedSet.provenance?.linearUnit||selectedSet.elevationUnits||'units unavailable')}</span></p>`:''}<label><span>Control point</span><select class="gcp-point-select" data-task-id="${esc(task.id)}">${points.map(point=>`<option value="${esc(point.id)}" ${point.id===workspace.pointId?'selected':''}>${esc(gcpPointName(point))}</option>`).join('')}</select></label>${selectedPoint?`<dl class="gcp-point-detail"><div><dt>Latitude</dt><dd>${esc(selectedPoint.latitude)}</dd></div><div><dt>Longitude</dt><dd>${esc(selectedPoint.longitude)}</dd></div><div><dt>Elevation</dt><dd>${esc(selectedPoint.elevationM)} m</dd></div></dl>`:''}<form class="gcp-candidate-form" data-task-id="${esc(task.id)}"><label><span>Image suggestions</span><select name="mode"><option value="auto" ${workspace.mode==='auto'?'selected':''}>Auto radius</option><option value="radius" ${workspace.mode==='radius'?'selected':''}>Fixed radius</option><option value="nearest" ${workspace.mode==='nearest'?'selected':''}>Nearest images</option></select></label>${workspace.mode==='radius'?field('Radius (metres)','radiusM',`type="number" min="0.1" max="100000" step="0.1" required value="${esc(workspace.radiusM)}"`):''}<button class="secondary-button">Refresh suggestions</button></form>${ranking?`<div class="gcp-ranking"><p>${esc(ranking.notice)}</p><small>${esc(ranking.mode)}${Number.isFinite(ranking.radiusM)?` · ${ranking.radiusM.toFixed(1)} m`:''} · visibility not confirmed</small>${(ranking.warnings||[]).map(warning=>`<span class="gcp-warning">${esc(warning)}</span>`).join('')}</div>`:''}<div class="gcp-candidates" aria-label="Suggested source images">${candidateRows||empty(selectedPoint?'No candidate images were found.':'Select a control point.')}</div></aside><div class="gcp-image-column">${active&&workspace.imageUrl?`<figure class="gcp-image-figure"><div class="gcp-image-stage"><img class="gcp-mark-image" src="${esc(workspace.imageUrl)}" alt="${esc(gcpImageName(active))}" data-task-id="${esc(task.id)}" draggable="false"><span class="gcp-marker" style="${gcpMarkerStyle(workspace)}" ${workspace.draftPixel?'':'hidden'} aria-hidden="true"></span></div><figcaption>Click the visible control point in the image, or enter exact pixel coordinates below.</figcaption></figure><form class="manage-form gcp-mark-form" data-task-id="${esc(task.id)}"><input type="hidden" name="imageFileId" value="${esc(active.id)}"><div class="gcp-pixel-fields">${field('Pixel X','pixelX',`type="number" min="0" step="any" required value="${esc(workspace.draftPixel?.pixelX??'')}"`)}${field('Pixel Y','pixelY',`type="number" min="0" step="any" required value="${esc(workspace.draftPixel?.pixelY??'')}"`)}</div><button class="primary-button">${workspace.editingId||activeMark?'Update mark':'Save mark'}</button></form>`:workspace.imageLoading?empty('Loading the private source image…'):empty(selectedPoint?'Select a suggested image to mark.':'Select a control point first.')}<section class="gcp-mark-list"><h4>Saved correspondences</h4>${correspondenceRows||empty('No image marks saved for this task.')}${correspondences.length>100?'<p class="form-note">Showing the first 100 saved marks.</p>':''}</section></div></div>`:empty('Import a GCP set to begin marking source images.')}</section>`}
function outputPanel(task,attempt,outputs,allowMutations=true){return`<section class="task-subsection"><div class="subsection-heading"><div><h3>Outputs and review</h3><p>Actions appear only when the API reports the corresponding integrity-checked artifact.</p></div></div><div class="data-list">${outputs.map(output=>`<div class="manage-row output-row"><div><strong>${esc(output.displayName||task.displayName)}</strong><small>${bytes(output.byteSize)} · ${output.assetCount??0} assets</small></div>${badge(output.status)}<div class="row-actions">${artifactActions(output,allowMutations)}${allowMutations&&output.activePublished&&(can('viewer.shares.create')||can('viewer.client_grants.manage'))?button('share-output',output.id,'Share'):''}</div></div>`).join('')||empty('No output is available yet.')}</div>${allowMutations&&attempt.status==='ready_for_review'&&can('viewer.processing.publish')?`<div class="inline-review"><p>Processing is complete. Review the isolated result before publishing verified assets.</p><div class="row-actions">${button('open-review',attempt.id,'Open review')}${button('publish-attempt',attempt.id,'Review & publish',true)}</div></div>`:''}</section>`}
function artifactActions(output,allowMutations=true){const kinds=new Set(Array.isArray(output.assetKinds)?output.assetKinds:[]),items=[];if(output.status==='published'&&output.viewSessionUrl)items.push(button('view-output',output.id,kinds.has('tiles')||kinds.has('ept')||kinds.has('glb')?'Open 3D model':'Open map',true));else if(allowMutations&&output.status==='ready'&&output.attemptId&&can('viewer.processing.publish'))items.push(button('open-review',output.attemptId,'Open review'));if(output.downloadUrl&&kinds.size)items.push(button('download-output',output.id,'Download',false,`data-url="${esc(output.downloadUrl)}"`));if(output.reportUrl&&kinds.has('report'))items.push(button('download-report',output.id,'Report',false,`data-url="${esc(output.reportUrl)}"`));if(allowMutations&&['ready','published','failed'].includes(output.status)&&can('viewer.processing.publish'))items.push(dangerButton('archive-output',output.id,'Archive'));if(allowMutations&&output.status==='archived'&&can('viewer.processing.publish'))items.push(dangerButton('trash-output',output.id,'Move to trash'));return items.join('')}
function logPanel(task,attempt,logs){const running=ACTIVE.has(attempt.status),text=logs.map(log=>`[${log.createdAt||''}] ${String(log.level||'info').toUpperCase()} ${log.message||''}`).join('\n');return`<section class="task-subsection"><div class="subsection-heading"><div><h3>Task output</h3><p>${running?'Live tail refreshes every five seconds.':'Latest bounded log tail.'}</p></div><div class="row-actions"><button class="secondary-button" data-action="download-logs" data-id="${esc(task.id)}">Download tail</button><button class="secondary-button" data-action="fullscreen-logs" data-id="${esc(task.id)}">Fullscreen</button></div></div><pre class="log-tail" tabindex="0" aria-label="Latest task output">${esc(text||'No task output has been recorded.')}</pre></section>`}

const providerName=type=>type==='clusterodm'?'ClusterODM':type==='nodeodm'?'NodeODM':'Unavailable';
const optionValue=value=>value===undefined||value===null?'Unavailable':typeof value==='string'?value:JSON.stringify(value);
function providers(){return`<div class="section-heading"><div><p class="eyebrow">Infrastructure</p><h2>Providers & nodes</h2><p>Add an endpoint once; Viewer probes and identifies the supported processing engine.</p></div><button class="primary-button" data-action="manage-providers">Manage nodes</button></div><div class="provider-summary">${state.providers.map(provider=>`<button class="provider-card" data-action="open-provider" data-id="${esc(provider.id)}"><span><strong>${esc(provider.displayName)}</strong><small>${providerName(provider.type)} · concurrency ${provider.admissionLimit}</small></span>${badge(provider.runtimeHealth||provider.lastHealth||'not probed')}</button>`).join('')||empty('No providers configured.')}</div>`}
function providerModal(selectedId=state.selectedProviderId){state.selectedProviderId=selectedId==='__new__'?'__new__':selectedId||state.providers[0]?.id||'__new__';const selected=state.providers.find(provider=>provider.id===state.selectedProviderId);openModal('Providers & nodes',`<div class="provider-master-detail"><aside><button class="secondary-button provider-add" data-action="provider-new">+ Add node</button><div class="provider-list">${state.providers.map(provider=>`<button class="provider-list-item ${provider.id===state.selectedProviderId?'active':''}" data-action="select-provider" data-id="${esc(provider.id)}"><span><strong>${esc(provider.displayName)}</strong><small>${esc(provider.endpoint)}</small></span>${badge(provider.runtimeHealth||provider.lastHealth||'unknown')}</button>`).join('')||empty('No nodes yet.')}</div></aside><section>${selected?providerDetail(selected):providerForm()}</section></div>`,'wide-modal');bindModalActions()}
function providerDetail(provider){const capabilities=provider.capabilities||{},options=Array.isArray(capabilities.options)?capabilities.options:[],presets=state.presets.filter(preset=>preset.providerType===provider.type&&preset.capabilityFingerprint===provider.capabilityFingerprint);return`<div class="provider-detail"><p class="eyebrow">Detected ${providerName(provider.type)}</p><h3>${esc(provider.displayName)}</h3><dl class="detail-list"><div><dt>Endpoint</dt><dd>${esc(provider.endpoint)}</dd></div><div><dt>API token</dt><dd>${provider.credential?.mode==='none'?'Not required':provider.credential?.configured?'Configured · hidden':'Not configured'}</dd></div><div><dt>Detected engine</dt><dd>${providerName(capabilities.providerType||provider.type)}</dd></div><div><dt>API version</dt><dd>${available(capabilities.apiVersion)}</dd></div><div><dt>Processing engine</dt><dd>${available(capabilities.engine)} · ${available(capabilities.engineVersion)}</dd></div><div><dt>Queue</dt><dd>${capabilities.taskQueueCount??'Unavailable'} queued · ${capabilities.maxParallelTasks??'Unavailable'} upstream slots</dd></div><div><dt>Viewer admission</dt><dd>${provider.admissionLimit} concurrent job${provider.admissionLimit===1?'':'s'}</dd></div><div><dt>Runtime health</dt><dd>${badge(provider.runtimeHealth||provider.lastHealth||'not probed')}</dd></div><div><dt>Presets</dt><dd>${presets.length}</dd></div><div><dt>Options</dt><dd>${options.length} detected</dd></div></dl>${presets.length?`<section class="provider-options"><h4>Processing presets</h4><div class="provider-option-list">${presets.map(preset=>`<div class="provider-option"><span><strong>${esc(preset.displayName)}</strong><small>${preset.builtIn?'Built in':preset.enabled?'Enabled':'Disabled'}</small></span><div class="row-actions">${preset.builtIn?'':`${button('edit-preset',preset.id,'Edit')}${button('delete-preset',preset.id,'Delete')}`}</div></div>`).join('')}</div></section>`:''}${options.length?`<section class="provider-options" aria-label="Detected processing options"><h4>Processing options</h4><div class="provider-option-list">${options.slice(0,100).map(option=>`<div class="provider-option"><span><strong>${esc(option.name)}</strong><small>${esc(option.type||'unknown')}</small></span><code>${esc(optionValue(option.value))}</code></div>`).join('')}</div>${options.length>100?`<p class="form-note">Showing the first 100 of ${options.length} options.</p>`:''}</section>`:''}<div class="row-actions">${button('edit-provider',provider.id,'Edit node')}${button('replace-provider-token',provider.id,provider.credential?.configured?'Replace token':'Set token')}${provider.credential?.configured?button('clear-provider-token',provider.id,'Clear token'):''}${button('new-preset',provider.id,'New preset')}${button('probe-provider',provider.id,'Re-probe')}${button('toggle-provider',provider.id,provider.enabled?'Disable':'Enable',!provider.enabled,`data-enabled="${!provider.enabled}"`)}</div><p class="form-note">Secrets are write-only and are never returned by the Viewer API. Engine type and capabilities come only from a successful endpoint probe.</p></div>`}
function providerForm(){return`<form id="provider-form" class="manage-form">${field('Node label','displayName','required maxlength="240"')}${field('HTTPS endpoint','endpoint','required type="url" placeholder="https://odm.example.com"')}${field('API token (if required)','token','type="password" autocomplete="new-password"')}<button class="primary-button">Detect & add node</button><p class="form-note">Viewer probes /info and /options, detects NodeODM or ClusterODM, and rejects unsupported or ambiguous endpoints. If supplied, the token is submitted once and is never displayed.</p></form>`}
function editProviderModal(id){const provider=state.providers.find(item=>item.id===id);if(!provider)return;openModal(`Edit ${provider.displayName}`,`<form id="provider-edit-form" class="manage-form"><input type="hidden" name="providerId" value="${esc(provider.id)}">${field('Node label','displayName',`required maxlength="240" value="${esc(provider.displayName)}"`)}${field('HTTPS endpoint','endpoint',`required type="url" value="${esc(provider.endpoint)}"`)}${field('Viewer admission limit','admissionLimit',`required type="number" min="1" max="100" step="1" value="${esc(provider.admissionLimit)}"`)}<button class="primary-button">Save node</button><p class="form-note">Changing the endpoint disables the node until its capabilities are probed again.</p></form>`);modalContent.querySelector('#provider-edit-form').onsubmit=async event=>{event.preventDefault();const input=values(event.currentTarget);modal.close();await mutate(`/api/v1/processing/providers/${encodeURIComponent(provider.id)}`,{method:'PATCH',body:{displayName:input.displayName,endpoint:input.endpoint,admissionLimit:Number(input.admissionLimit)}},'Provider updated');providerModal(provider.id)}}
function providerTokenModal(id){const provider=state.providers.find(item=>item.id===id);if(!provider)return;openModal(`API token for ${provider.displayName}`,`<form id="provider-token-form" class="manage-form">${field('New API token','token','required type="password" autocomplete="new-password"')}<button class="primary-button">Store token</button><p class="form-note">The token is encrypted at rest, submitted once, and never displayed again.</p></form>`);modalContent.querySelector('#provider-token-form').onsubmit=async event=>{event.preventDefault();const token=event.currentTarget.elements.token.value;modal.close();await mutate(`/api/v1/processing/providers/${encodeURIComponent(provider.id)}/credential`,{method:'PUT',body:{token}},'Provider token stored');providerModal(provider.id)}}
function presetModal(providerId,presetId=null){const provider=state.providers.find(item=>item.id===providerId),preset=state.presets.find(item=>item.id===presetId);if(!provider)return;openModal(preset?'Edit processing preset':'New processing preset',`<form id="preset-form" class="manage-form">${field('Preset name','displayName',`required maxlength="240" value="${esc(preset?.displayName||'')}"`)}${field('Description','description',`maxlength="1000" value="${esc(preset?.description||'')}"`)}<label><span>Provider options (JSON)</span><textarea name="options" rows="10" spellcheck="false" required>${esc(JSON.stringify(preset?.options||{},null,2))}</textarea></label><label class="check"><input type="checkbox" name="enabled" ${preset?.enabled===false?'':'checked'}> Enabled</label><button class="primary-button">${preset?'Save preset':'Create preset'}</button><p class="form-note">Options are checked against the node's latest detected capabilities before they are stored.</p></form>`);modalContent.querySelector('#preset-form').onsubmit=async event=>{event.preventDefault();let options;try{options=JSON.parse(event.currentTarget.elements.options.value)}catch{return toast('Provider options must be valid JSON',true)}if(!options||Array.isArray(options)||typeof options!=='object')return toast('Provider options must be a JSON object',true);const body={displayName:event.currentTarget.elements.displayName.value,description:event.currentTarget.elements.description.value,providerId:provider.id,options,enabled:event.currentTarget.elements.enabled.checked},path=preset?`/api/v1/processing/presets/${encodeURIComponent(preset.id)}`:'/api/v1/processing/presets';modal.close();await mutate(path,{method:preset?'PATCH':'POST',body},preset?'Preset updated':'Preset created');providerModal(provider.id)}}

function diagnostics(){const spaces=state.storage?.storage||{},trash=state.storage?.trash?.items||[],lifecycle=state.ready?.lifecycle||[],failed=state.failedMutations||[];const failedRows=failed.map(item=>`<div class="manage-row"><div><strong>${esc(item.type)} ${esc(item.entityType)}</strong><small>${esc(item.entityId)}</small><small>${esc(item.errorCode||'lifecycle_failed')}: ${esc(item.errorMessage||'The storage operation requires operator repair.')}</small></div>${badge(item.status)}<div class="row-actions">${can('viewer.storage.purge')?button('retry-storage-mutation',item.id,'Retry'):''}</div></div>`).join('')||empty('No failed storage mutations.');const trashRows=trash.map(item=>`<div class="manage-row"><div><strong>${esc(item.displayName||item.entityType)}</strong><small>${esc(item.entityType)} · ${bytes(item.byteSize)} · purge after ${dateTime(item.purgeAfter)}</small></div>${badge('trash')}<div class="row-actions">${can('viewer.storage.purge')?`${button('restore-trash',item.id,'Restore')}${dangerButton('purge-trash',item.id,'Delete permanently',`data-entity-id="${esc(item.entityId)}"`)}`:''}</div></div>`).join('')||empty('Trash is empty.');return`<div class="metric-grid">${Object.entries(spaces).map(([key,item])=>metric(key,bytes(item.usedBytes),`${bytes(item.availableBytes)} available`)).join('')}${metric('Processing worker',state.ready?.worker?.live?'Live':'Unavailable','Queue and worker health')}${metric('Platform',state.ready?.ok?'Ready':'Attention needed','Aggregated readiness')}</div><div class="diagnostic-grid top-gap">${card('Queue & provider health',`<div class="data-list">${state.providers.map(provider=>`<div class="manage-row"><div><strong>${esc(provider.displayName)}</strong><small>${esc(provider.endpoint)}</small></div>${badge(provider.runtimeHealth||provider.lastHealth||'unknown')}<div></div></div>`).join('')||empty('No providers configured.')} ${lifecycle.map(item=>`<div class="manage-row"><div><strong>${esc(item.status)}</strong><small>Storage lifecycle operations</small></div><strong>${item.count}</strong><div></div></div>`).join('')}</div>`)}${card('Failed storage mutations',`<div class="data-list">${failedRows}</div><p class="form-note">Repair the reported storage conflict before retrying. A failed row keeps processing readiness blocked.</p>`)}${card('Storage trash & recovery',`<div class="data-list">${trashRows}</div><p class="form-note">Permanent deletion requires typing the exact dataset or output identifier and cannot be undone.</p>`)}</div>`}

function render(){clearInterval(state.logTimer);renderNav();document.querySelector('#page-title').textContent=NAV.find(item=>item[0]===state.section)?.[2]||'Dashboard';content.innerHTML=({dashboard,providers,diagnostics}[state.section]||dashboard)();bind();if(state.expandedTaskId){const task=state.tasks.find(item=>item.id===state.expandedTaskId);if(ACTIVE.has(task?.latestAttempt?.status))state.logTimer=setInterval(()=>refreshTaskDetails(task.id,true),5000)}}
function bind(){content.querySelectorAll('[data-section]').forEach(element=>element.onclick=()=>{state.section=element.dataset.section;render()});content.querySelectorAll('[data-action]').forEach(element=>element.onclick=()=>action(element));const filter=content.querySelector('#project-filter');if(filter)filter.oninput=()=>{state.projectQuery=filter.value;const query=state.projectQuery.trim().toLocaleLowerCase('en-US');content.querySelectorAll('[data-project-name]').forEach(row=>row.hidden=Boolean(query&&!row.dataset.projectName.includes(query)))};const datasetForm=content.querySelector('#dataset-form');if(datasetForm)datasetForm.onsubmit=event=>{event.preventDefault();mutate('/api/v1/datasets',{method:'POST',body:values(datasetForm)},'Dataset draft created')};content.querySelectorAll('.gcp-import-form').forEach(form=>form.onsubmit=importGcp);content.querySelectorAll('.gcp-set-select').forEach(select=>select.onchange=()=>changeGcpSet(select.dataset.taskId,select.value));content.querySelectorAll('.gcp-point-select').forEach(select=>select.onchange=()=>changeGcpPoint(select.dataset.taskId,select.value));content.querySelectorAll('.gcp-candidate-form').forEach(form=>{form.elements.mode.onchange=()=>{gcpWorkspace(form.dataset.taskId).mode=form.elements.mode.value;render()};form.onsubmit=event=>refreshGcpCandidates(event)});content.querySelectorAll('.gcp-mark-form').forEach(form=>{form.onsubmit=saveGcpMark;form.oninput=()=>setGcpDraft(form.dataset.taskId,Number(form.elements.pixelX.value),Number(form.elements.pixelY.value))});content.querySelectorAll('.gcp-mark-image').forEach(image=>{image.onload=()=>configureGcpImage(image);image.onclick=event=>markGcpImage(event)})}
async function action(element){
  const action=element.dataset.action,id=element.dataset.id,taskId=element.dataset.taskId;
  if(action==='new-project')return newProjectModal();
  if(action==='open-project'){releaseAllGcpImages();state.selectedProjectId=id;state.expandedTaskId=null;return render()}
  if(action==='close-project'){releaseAllGcpImages();state.selectedProjectId=null;state.expandedTaskId=null;return render()}
  if(action==='archive-project')return confirmedMutation('Archive this project? Archived projects are read-only and cannot be restored in the Viewer.',`/api/v1/projects/${encodeURIComponent(id)}/archive`,{method:'POST',body:{}},'Project archived');
  if(action==='project-import'||action==='upload-dataset')return importModal(action==='upload-dataset'?null:id,action==='upload-dataset'?id:null);
  if(action==='project-process')return processModal(id);
  if(action==='project-share')return openShareModal(id);
  if(action==='archive-dataset')return confirmedMutation('Archive this dataset? It must not have an active operation or non-archived task.',`/api/v1/datasets/${encodeURIComponent(id)}/archive`,{method:'POST',body:{}},'Dataset archived');
  if(action==='trash-dataset')return confirmedMutation('Move this dataset to recoverable trash for 14 days?',`/api/v1/datasets/${encodeURIComponent(id)}`,{method:'DELETE',body:{}},'Dataset moved to trash');
  if(action==='toggle-task'){if(state.expandedTaskId===id){releaseGcpImage(gcpWorkspace(id));state.expandedTaskId=null;return render()}if(state.expandedTaskId)releaseGcpImage(gcpWorkspace(state.expandedTaskId));state.expandedTaskId=id;state.taskDetails[id]={loading:true};render();return refreshTaskDetails(id)}
  if(action==='gcp-open-image')return openGcpImage(taskId,id);
  if(action==='gcp-edit-mark')return editGcpMark(taskId,id);
  if(action==='gcp-delete-mark')return deleteGcpMark(taskId,id);
  if(action==='edit-task')return editTask(id);
  if(action==='archive-task')return confirmedMutation('Archive this task? Archived tasks are read-only and cannot be restored in the Viewer.',`/api/v1/tasks/${encodeURIComponent(id)}/archive`,{method:'POST',body:{}},'Task archived');
  if(action==='cancel-attempt'||action==='retry-attempt')return mutate(`/api/v1/attempts/${encodeURIComponent(id)}/${action.startsWith('cancel')?'cancel':'retry'}`,{method:'POST',body:{}},action.startsWith('cancel')?'Attempt cancelled':'Task restarted');
  if(action==='restart-task')return restartTask(id);
  if(action==='open-review')return openReview(id);
  if(action==='publish-attempt')return publishAttempt(id);
  if(action==='view-output')return viewPublishedOutput(id);
  if(action==='download-output'||action==='download-report')return downloadOutputAsset(id,element.dataset.url,action==='download-report');
  if(action==='share-output')return openShareModal(state.selectedProjectId,id);
  if(action==='archive-output')return confirmedMutation('Archive this output? Published assets will be unpublished. Active links or viewing sessions must be revoked first.',`/api/v1/processing/outputs/${encodeURIComponent(id)}/archive`,{method:'POST',body:{}},'Output archived');
  if(action==='trash-output')return confirmedMutation('Move this archived output to recoverable trash for 14 days?',`/api/v1/processing/outputs/${encodeURIComponent(id)}`,{method:'DELETE',body:{}},'Output moved to trash');
  if(action==='download-logs')return downloadLogs(id);
  if(action==='fullscreen-logs')return fullscreenLogs(id);
  if(action==='manage-providers')return providerModal();
  if(action==='open-provider')return providerModal(id);
  if(action==='retry-storage-mutation')return confirmedMutation('Retry this failed storage mutation after repairing the reported conflict?',`/api/v1/storage/mutations/${encodeURIComponent(id)}/retry`,{method:'POST',body:{}},'Storage mutation completed');
  if(action==='restore-trash')return mutate(`/api/v1/storage/trash/${encodeURIComponent(id)}/restore`,{method:'POST',body:{}},'Item restored');
  if(action==='purge-trash')return purgeTrash(id,element.dataset.entityId);
}

async function refreshTaskDetails(taskId,quiet=false){const task=state.tasks.find(item=>item.id===taskId),attemptId=task?.latestAttempt?.id,previous=state.taskDetails[taskId];if(!task)return;const requests=[api(`/api/v1/tasks/${encodeURIComponent(taskId)}`),api(`/api/v1/tasks/${encodeURIComponent(taskId)}/storage?limit=100`),api(`/api/v1/datasets/${encodeURIComponent(task.datasetId)}/gcp-sets`),api(`/api/v1/tasks/${encodeURIComponent(taskId)}/attempts?limit=100`)];if(attemptId)requests.push(api(`/api/v1/attempts/${encodeURIComponent(attemptId)}?logLimit=100`));const results=await Promise.allSettled(requests),refreshedTask=results[0].value?.task||task,attemptResult=attemptId?results[4]?.value:null;state.tasks=state.tasks.map(item=>item.id===taskId?refreshedTask:item);state.taskDetails[taskId]={task:refreshedTask,storage:results[1].value||null,gcp:quiet&&previous?.gcp?previous.gcp:(results[2].value||{sets:[]}),attempts:results[3].value?.attempts||previous?.attempts||[],attempt:attemptResult?.attempt||refreshedTask.latestAttempt,logs:(attemptResult?.logs||[]).slice(-100)};if(!quiet){try{await refreshGcpWorkspace(taskId,false)}catch(error){state.taskDetails[taskId].gcp={...(state.taskDetails[taskId].gcp||{sets:[]}),error:error.message}}}if(state.expandedTaskId===taskId){render();if(!quiet)document.querySelector(`[data-action="toggle-task"][data-id="${CSS.escape(taskId)}"]`)?.focus()}}

function releaseGcpImage(workspace){if(workspace?.imageUrl){URL.revokeObjectURL(workspace.imageUrl);workspace.imageUrl=null}if(workspace){workspace.activeImage=null;workspace.imageLoading=false;workspace.draftPixel=null;workspace.editingId=null}}
function releaseAllGcpImages(){Object.values(state.gcpWorkspaces).forEach(releaseGcpImage)}
async function refreshGcpWorkspace(taskId,shouldRender=true){const task=state.tasks.find(item=>item.id===taskId),detail=state.taskDetails[taskId],workspace=gcpWorkspace(taskId);if(!task||!detail)return;let sets=detail.gcp?.sets||[];if(!sets.some(set=>set.id===workspace.setId)){workspace.setId=sets[0]?.id||null;workspace.pointId=null;releaseGcpImage(workspace)}let points=[];if(workspace.setId){const setPayload=await api(`/api/v1/gcp-sets/${encodeURIComponent(workspace.setId)}`);points=setPayload.points||[];workspace.pointCache[workspace.setId]=points;sets=sets.map(set=>set.id===workspace.setId?{...set,...setPayload.set}:set);if(!points.some(point=>point.id===workspace.pointId)){workspace.pointId=points[0]?.id||null;releaseGcpImage(workspace)}}const correspondences=(await api(`/api/v1/tasks/${encodeURIComponent(taskId)}/gcp-correspondences`)).correspondences||[];let candidates=[],ranking=null;if(workspace.pointId){const query=new URLSearchParams({pointId:workspace.pointId,mode:workspace.mode,limit:'24'});if(workspace.mode==='radius')query.set('radiusM',String(workspace.radiusM));const response=await api(`/api/v1/datasets/${encodeURIComponent(task.datasetId)}/gcp-images?${query}`);candidates=response.images||[];ranking=response.ranking||null}detail.gcp={sets,points,correspondences,candidates,ranking,error:null};if(shouldRender&&state.expandedTaskId===taskId)render()}
async function changeGcpSet(taskId,setId){const workspace=gcpWorkspace(taskId);workspace.setId=setId;workspace.pointId=null;releaseGcpImage(workspace);try{await refreshGcpWorkspace(taskId)}catch(error){toast(error.message,true)}}
async function changeGcpPoint(taskId,pointId){const workspace=gcpWorkspace(taskId);workspace.pointId=pointId;releaseGcpImage(workspace);try{await refreshGcpWorkspace(taskId)}catch(error){toast(error.message,true)}}
async function refreshGcpCandidates(event){event.preventDefault();const form=event.currentTarget,workspace=gcpWorkspace(form.dataset.taskId);workspace.mode=form.elements.mode.value;if(workspace.mode==='radius')workspace.radiusM=Number(form.elements.radiusM.value);try{await refreshGcpWorkspace(form.dataset.taskId)}catch(error){toast(error.message,true)}}
async function privateGcpImage(datasetId,fileId){const response=await fetch(`/api/v1/datasets/${encodeURIComponent(datasetId)}/gcp-images/${encodeURIComponent(fileId)}/content`,{headers:{Authorization:`Bearer ${state.token}`,Accept:'image/*'},cache:'no-store'});if(response.status===401){clearWorkspaceAuthorization();throw responseError('authorization_required',401)}if(response.status===403)throw responseError('Your current Viewer grant does not permit private source-image access',403);if(!response.ok){let payload;try{payload=await response.json()}catch{}throw responseError(payload?.message||payload?.error||`Image request failed (${response.status})`,response.status)}const type=response.headers.get('content-type')||'';if(!type.toLocaleLowerCase('en-US').startsWith('image/'))throw Error('The selected file is not a supported source image');return URL.createObjectURL(await response.blob())}
async function openGcpImage(taskId,imageFileId,editingId=null){const task=state.tasks.find(item=>item.id===taskId),detail=state.taskDetails[taskId],workspace=gcpWorkspace(taskId);if(!task||!detail||!workspace.pointId)return;const image=detail.gcp?.candidates?.find(candidate=>candidate.id===imageFileId)||{id:imageFileId,relativePath:imageFileId,width:null,height:null},mark=detail.gcp?.correspondences?.find(item=>item.id===editingId)||detail.gcp?.correspondences?.find(item=>item.pointId===workspace.pointId&&item.imageFileId===imageFileId);releaseGcpImage(workspace);workspace.activeImage={...image};workspace.imageLoading=true;workspace.editingId=mark?.id||null;workspace.draftPixel=mark?{pixelX:mark.pixelX,pixelY:mark.pixelY}:null;render();try{workspace.imageUrl=await privateGcpImage(task.datasetId,imageFileId);workspace.imageLoading=false;render();queueMicrotask(()=>content.querySelector('.gcp-mark-image')?.focus())}catch(error){workspace.imageLoading=false;workspace.activeImage=null;if(error.status!==401){toast(error.message,true);render()}}}
function configureGcpImage(image){const workspace=gcpWorkspace(image.dataset.taskId);if(!workspace.activeImage)return;workspace.activeImage.width=image.naturalWidth;workspace.activeImage.height=image.naturalHeight;image.tabIndex=0;image.setAttribute('role','button');image.setAttribute('aria-label',`${image.alt}. Click to set the control point pixel.`);const form=content.querySelector(`.gcp-mark-form[data-task-id="${CSS.escape(image.dataset.taskId)}"]`);if(form){form.elements.pixelX.max=String(Math.max(0,image.naturalWidth-0.001));form.elements.pixelY.max=String(Math.max(0,image.naturalHeight-0.001))}positionGcpMarker(image.dataset.taskId)}
function positionGcpMarker(taskId){const workspace=gcpWorkspace(taskId),marker=content.querySelector(`.gcp-mark-image[data-task-id="${CSS.escape(taskId)}"]`)?.parentElement.querySelector('.gcp-marker');if(!marker)return;const style=gcpMarkerStyle(workspace);marker.hidden=!style;if(style)marker.style.cssText=style}
function setGcpDraft(taskId,pixelX,pixelY){const workspace=gcpWorkspace(taskId);workspace.draftPixel=Number.isFinite(pixelX)&&Number.isFinite(pixelY)?{pixelX,pixelY}:null;positionGcpMarker(taskId)}
function markGcpImage(event){const image=event.currentTarget,rect=image.getBoundingClientRect();if(!rect.width||!rect.height||!image.naturalWidth||!image.naturalHeight)return;const pixelX=Math.max(0,Math.min(image.naturalWidth-0.001,(event.clientX-rect.left)*image.naturalWidth/rect.width)),pixelY=Math.max(0,Math.min(image.naturalHeight-0.001,(event.clientY-rect.top)*image.naturalHeight/rect.height)),form=content.querySelector(`.gcp-mark-form[data-task-id="${CSS.escape(image.dataset.taskId)}"]`);if(!form)return;form.elements.pixelX.value=pixelX.toFixed(2);form.elements.pixelY.value=pixelY.toFixed(2);setGcpDraft(image.dataset.taskId,pixelX,pixelY)}
async function saveGcpMark(event){event.preventDefault();const form=event.currentTarget,taskId=form.dataset.taskId,workspace=gcpWorkspace(taskId),pixelX=Number(form.elements.pixelX.value),pixelY=Number(form.elements.pixelY.value),imageFileId=form.elements.imageFileId.value,existing=state.taskDetails[taskId]?.gcp?.correspondences?.find(item=>item.id===workspace.editingId)||state.taskDetails[taskId]?.gcp?.correspondences?.find(item=>item.pointId===workspace.pointId&&item.imageFileId===imageFileId);if(!workspace.pointId||!Number.isFinite(pixelX)||!Number.isFinite(pixelY))return toast('Select a control point and valid image coordinates',true);if(state.busy)return;state.busy=true;try{const result=existing?await api(`/api/v1/gcp-correspondences/${encodeURIComponent(existing.id)}`,{method:'PATCH',body:{pixelX,pixelY}}):await api(`/api/v1/tasks/${encodeURIComponent(taskId)}/gcp-correspondences`,{method:'POST',body:{pointId:workspace.pointId,imageFileId,pixelX,pixelY}});workspace.editingId=result.correspondence.id;workspace.draftPixel={pixelX:result.correspondence.pixelX,pixelY:result.correspondence.pixelY};toast(existing?'GCP image mark updated':'GCP image mark saved');await refreshGcpWorkspace(taskId)}catch(error){toast(error.message,true)}finally{state.busy=false}}
async function editGcpMark(taskId,id){const detail=state.taskDetails[taskId],workspace=gcpWorkspace(taskId),mark=detail?.gcp?.correspondences?.find(item=>item.id===id);if(!mark)return;let located=null;for(const set of detail.gcp.sets||[]){let points=workspace.pointCache[set.id];if(!points){try{points=(await api(`/api/v1/gcp-sets/${encodeURIComponent(set.id)}`)).points||[];workspace.pointCache[set.id]=points}catch{continue}}if(points.some(point=>point.id===mark.pointId)){located=set.id;break}}if(!located)return toast('The marked control point is no longer available',true);workspace.setId=located;workspace.pointId=mark.pointId;try{await refreshGcpWorkspace(taskId,false);await openGcpImage(taskId,mark.imageFileId,id)}catch(error){toast(error.message,true)}}
async function deleteGcpMark(taskId,id){if(!confirm('Delete this saved image correspondence?'))return;if(state.busy)return;state.busy=true;try{await api(`/api/v1/gcp-correspondences/${encodeURIComponent(id)}`,{method:'DELETE'});const workspace=gcpWorkspace(taskId);if(workspace.editingId===id){workspace.editingId=null;workspace.draftPixel=null}toast('GCP image mark deleted');await refreshGcpWorkspace(taskId)}catch(error){toast(error.message,true)}finally{state.busy=false}}
