async function downloadOutputAsset(id,url,isReport){if(!url)return toast('This output does not expose that artifact',true);const output=state.outputs.find(item=>item.id===id),suffix=isReport?'report.pdf':String(url).split('/').at(-1)||'output';try{await authenticatedDownload(url,`${safeFileName(output?.displayName)}-${safeFileName(suffix)}`)}catch(error){toast(error.message,true)}}
async function purgeTrash(id,entityId){const typed=prompt(`Permanent deletion cannot be undone. Type the exact identifier to continue:\n${entityId}`);if(typed!==entityId)return typed===null?undefined:toast('Identifier did not match; nothing was deleted',true);return mutate(`/api/v1/storage/trash/${encodeURIComponent(id)}`,{method:'DELETE',body:{typedId:typed}},'Item permanently deleted')}
async function importGcp(event){event.preventDefault();const form=event.currentTarget,file=form.elements.file.files[0];if(!file)return;const format=form.elements.format.value,contentText=await file.text(),previewPath=`/api/v1/datasets/${encodeURIComponent(form.dataset.datasetId)}/gcp-sets/import-preview`;let declarations,preview;try{preview=await api(previewPath,{method:'POST',body:{format,content:contentText}})}catch(error){if(format!=='emlid-all-columns-v1'||!error.message.includes('units are not explicit'))return toast(error.message,true);const unit=prompt('This file does not declare projected units. Enter m or ftUS to continue:');if(!['m','ftUS'].includes(unit))return toast('GCP import cancelled; choose m or ftUS only',true);declarations={linearUnit:unit};try{preview=await api(previewPath,{method:'POST',body:{format,content:contentText,declarations}})}catch(retryError){return toast(retryError.message,true)}}const body={displayName:form.elements.displayName.value,format,fileName:file.name,content:contentText,...(declarations?{declarations}:{})};openModal('Confirm GCP import',`<div class="gcp-preview"><p>The API parsed <strong>${preview.pointCount}</strong> points. Confirm this authoritative mapping before writing the set.</p><dl class="detail-list"><div><dt>Point identifier</dt><dd>${esc(preview.columns?.id||'Unavailable')}</dd></div><div><dt>Survey coordinates</dt><dd>${esc((preview.columns?.authoritative||[]).join(', ')||'Unavailable')}</dd></div><div><dt>Cross-check only</dt><dd>${esc((preview.columns?.crossCheck||[]).join(', ')||'Unavailable')}</dd></div><div><dt>Coordinate system</dt><dd>${esc(preview.provenance?.coordinateSystem||'Unavailable')}</dd></div><div><dt>Vertical datum</dt><dd>${esc(preview.provenance?.verticalDatum||'Unavailable')}</dd></div><div><dt>Linear unit</dt><dd>${esc(preview.provenance?.linearUnit||'Unavailable')}</dd></div></dl>${(preview.warnings||[]).map(warning=>`<p class="form-note">Warning: ${esc(warning)}</p>`).join('')}<div class="row-actions"><button class="secondary-button modal-cancel">Cancel</button><button class="primary-button gcp-confirm">Confirm import</button></div></div>`);modalContent.querySelector('.modal-cancel').onclick=()=>modal.close();modalContent.querySelector('.gcp-confirm').onclick=async()=>{modal.close();await mutate(`/api/v1/datasets/${encodeURIComponent(form.dataset.datasetId)}/gcp-sets/import`,{method:'POST',body:{...body,confirmationToken:preview.confirmationToken}},'GCP set imported');await refreshTaskDetails(form.dataset.taskId)}}

function shareModal(projectId,onlyOutputId=null){const project=state.projects.find(item=>item.id===projectId),taskIds=new Set(state.tasks.filter(task=>task.projectId===projectId).map(task=>task.id)),published=state.outputs.filter(output=>output.activePublished&&taskIds.has(output.taskId)&&(!onlyOutputId||output.id===onlyOutputId)),access=state.clientAccess,portalProjects=access?.projects||[],associations=access?.associations||[],grants=access?.grants||[];openModal(`Share ${project?.displayName||'project'}`,`<div class="share-columns">${access?card('Authenticated client access',`<form id="client-grant-form" class="manage-form"><label><span>Client Portal project</span><select name="projectId" required><option value="">Select client project</option>${portalProjects.map(item=>`<option value="${esc(item.id)}" data-account-id="${esc(item.accountId||item.account_id||'')}">${esc(item.clientName||item.client_name||'Client')} — ${esc(item.name||item.projectName||item.project_name||item.id)}</option>`).join('')}</select></label><label><span>Access scope</span><select name="scopeType"><option value="project">Entire project</option><option value="task">One published task</option></select></label><label class="client-task-field" hidden><span>Published task</span><select name="associationId"><option value="">Select a task</option>${associations.map(item=>`<option value="${esc(item.id)}" data-project-id="${esc(item.projectId||item.project_id||'')}">${esc(item.modelTitle||item.model_title||item.displayName||item.id)}</option>`).join('')}</select></label>${field('Expiry (optional)','expiresAt','type="datetime-local"')}<label class="check"><input type="checkbox" name="includeFuturePublished" checked> Include future published tasks</label><label class="check"><input type="checkbox" name="measure" checked> Measurements</label><label class="check"><input type="checkbox" name="cameras" checked> Camera positions</label><label class="check"><input type="checkbox" name="download"> Downloads</label><button class="primary-button">Grant client access</button></form><div class="data-list top-gap">${grants.map(grant=>`<div class="manage-row"><div><strong>${esc(grant.clientName||grant.client_name||grant.accountId)}</strong><small>${esc(grant.projectName||grant.project_name||grant.projectId)}</small></div>${badge(grant.status||'active')}<div>${(grant.status||'active')==='active'?button('revoke-client-grant',grant.id,'Revoke'):''}</div></div>`).join('')||empty('No authenticated client grants.')}</div>`):card('Authenticated client access',empty('Your current grant does not include client-access management.'))}<div>${state.lastShareUrl?card('New public link — copy now',`<div class="share-result"><input readonly value="${esc(state.lastShareUrl)}"><button class="primary-button" data-action="copy-share" data-url="${esc(state.lastShareUrl)}">Copy</button></div>`):''}${published.map(output=>card(output.displayName||'Published task',`<form class="manage-form share-form" data-output-id="${esc(output.id)}">${field('Link label','label','maxlength="120"')}${field('Optional password','password','type="password" minlength="8" autocomplete="new-password"')}${field('Expiry','expiresAt','type="datetime-local"')}<label class="check"><input type="checkbox" name="measure" checked> Measurements</label><label class="check"><input type="checkbox" name="cameras" checked> Camera positions</label><label class="check"><input type="checkbox" name="download"> Downloads</label><button class="primary-button">Create public link</button></form><div class="data-list top-gap">${(state.shares[output.id]||[]).map(share=>`<div class="manage-row"><div><strong>${esc(share.label||'Public link')}</strong><small>${share.hasPassword?'Password protected':'No password'}</small></div>${badge(share.revokedAt?'revoked':'active')}<div>${!share.revokedAt?button('revoke-share',share.id,'Revoke'):''}</div></div>`).join('')||empty('No public links.')}</div>`)).join('')||card('Published tasks',empty('No current published task is available to share.'))}</div></div>`,'wide-modal');bindShareModal()}
function bindShareModal(){const grantForm=modalContent.querySelector('#client-grant-form');if(grantForm){const sync=()=>{const task=grantForm.elements.scopeType.value==='task',projectId=grantForm.elements.projectId.value;grantForm.querySelector('.client-task-field').hidden=!task;grantForm.elements.associationId.required=task;grantForm.elements.includeFuturePublished.disabled=task;if(task)grantForm.elements.includeFuturePublished.checked=false;for(const option of grantForm.elements.associationId.options){if(!option.value)continue;option.hidden=option.dataset.projectId!==projectId;option.disabled=option.hidden}if(grantForm.elements.associationId.selectedOptions[0]?.disabled)grantForm.elements.associationId.value=''};grantForm.elements.scopeType.onchange=sync;grantForm.elements.projectId.onchange=sync;sync();grantForm.onsubmit=event=>{event.preventDefault();const selected=grantForm.elements.projectId.selectedOptions[0],scopeType=grantForm.elements.scopeType.value,body={grant:{accountId:selected.dataset.accountId,projectId:selected.value,scopeType,associationId:scopeType==='task'?grantForm.elements.associationId.value:null,includeFuturePublished:scopeType==='project'&&grantForm.elements.includeFuturePublished.checked,expiresAt:grantForm.elements.expiresAt.value?new Date(grantForm.elements.expiresAt.value).toISOString():null,permissions:{measure:grantForm.elements.measure.checked,cameras:grantForm.elements.cameras.checked,download:grantForm.elements.download.checked}}};modal.close();mutate('/api/v1/workspace/client-grants',{method:'POST',body},'Client access granted')}}modalContent.querySelectorAll('.share-form').forEach(form=>form.onsubmit=async event=>{event.preventDefault();const input=values(form),body={label:input.label,expiresAt:input.expiresAt?new Date(input.expiresAt).toISOString():null,permissions:{view:true,measure:form.elements.measure.checked,cameras:form.elements.cameras.checked,download:form.elements.download.checked}};if(input.password)body.password=input.password;try{const result=await api(`/api/v1/processing/outputs/${encodeURIComponent(form.dataset.outputId)}/shares`,{method:'POST',body});state.lastShareUrl=result.viewUrl;await navigator.clipboard?.writeText(result.viewUrl);toast('Public link created and copied');await load();shareModal(state.selectedProjectId)}catch(error){toast(error.message,true)}});modalContent.querySelectorAll('[data-action="revoke-client-grant"]').forEach(element=>element.onclick=()=>{const reason=prompt('Reason for revoking this client access');if(reason){modal.close();mutate('/api/v1/workspace/client-grants',{method:'DELETE',body:{grantId:element.dataset.id,reason}},'Client access revoked')}});modalContent.querySelectorAll('[data-action="revoke-share"]').forEach(element=>element.onclick=()=>{modal.close();mutate(`/api/v1/processing/shares/${encodeURIComponent(element.dataset.id)}`,{method:'DELETE',body:{}},'Link revoked')});modalContent.querySelectorAll('[data-action="copy-share"]').forEach(element=>element.onclick=async()=>{await navigator.clipboard.writeText(element.dataset.url);toast('Link copied')})}
function bindModalActions(){modalContent.querySelectorAll('[data-action]').forEach(element=>element.onclick=async()=>{const action=element.dataset.action,id=element.dataset.id;if(action==='provider-new')return providerModal('__new__');if(action==='select-provider')return providerModal(id);if(action==='edit-provider')return editProviderModal(id);if(action==='replace-provider-token')return providerTokenModal(id);if(action==='clear-provider-token'){if(!confirm('Clear this node token and disable the provider?'))return;modal.close();await mutate(`/api/v1/processing/providers/${encodeURIComponent(id)}/credential`,{method:'DELETE',body:{}},'Provider token cleared');return providerModal(id)}if(action==='new-preset')return presetModal(id);if(action==='edit-preset'){const preset=state.presets.find(item=>item.id===id),provider=state.providers.find(item=>item.type===preset?.providerType&&item.capabilityFingerprint===preset?.capabilityFingerprint);return provider?presetModal(provider.id,id):toast('The preset no longer matches a current provider probe',true)}if(action==='delete-preset'){const preset=state.presets.find(item=>item.id===id),provider=state.providers.find(item=>item.type===preset?.providerType&&item.capabilityFingerprint===preset?.capabilityFingerprint);if(!provider||!confirm(`Delete preset "${preset.displayName}"?`))return;modal.close();await mutate(`/api/v1/processing/presets/${encodeURIComponent(id)}`,{method:'DELETE',body:{}},'Preset deleted');return providerModal(provider.id)}if(action==='probe-provider'){modal.close();await mutate(`/api/v1/processing/providers/${encodeURIComponent(id)}/capabilities/probe`,{method:'POST',body:{}},'Provider capabilities refreshed');return providerModal(id)}if(action==='toggle-provider'){modal.close();await mutate(`/api/v1/processing/providers/${encodeURIComponent(id)}`,{method:'PATCH',body:{enabled:element.dataset.enabled==='true'}},'Provider updated');return providerModal(id)}});const form=modalContent.querySelector('#provider-form');if(form)form.onsubmit=async event=>{event.preventDefault();if(state.busy)return;const input=values(form),submit=form.querySelector('button[type="submit"],button:not([type])'),body={displayName:input.displayName,endpoint:input.endpoint};if(input.token)body.credential={token:input.token};state.busy=true;submit.disabled=true;submit.textContent='Detecting…';try{const result=await api('/api/v1/processing/providers',{method:'POST',body});toast(`${providerName(result.detection?.providerType)} detected and added`);modal.close();await load();providerModal(result.provider.id)}catch(error){toast(error.message,true);submit.disabled=false;submit.textContent='Detect & add node'}finally{state.busy=false}}}

function logText(taskId){return(state.taskDetails[taskId]?.logs||[]).map(log=>`[${log.createdAt||''}] ${String(log.level||'info').toUpperCase()} ${log.message||''}`).join('\n')||'No task output has been recorded.'}
function downloadLogs(taskId){const task=state.tasks.find(item=>item.id===taskId),link=document.createElement('a');link.href=URL.createObjectURL(new Blob([logText(taskId)],{type:'text/plain'}));link.download=`${(task?.displayName||'task').replace(/[^a-z0-9_-]+/gi,'-')}-log-tail.txt`;link.click();URL.revokeObjectURL(link.href)}
function fullscreenLogs(taskId){openModal('Task output',`<pre class="log-tail fullscreen-log" tabindex="0">${esc(logText(taskId))}</pre>`,'wide-modal')}
async function digest(buffer){return[...new Uint8Array(await crypto.subtle.digest('SHA-256',buffer))].map(value=>value.toString(16).padStart(2,'0')).join('')}
async function uploadFiles(form){const files=[...form.elements.files.files],datasetId=form.elements.datasetId.value,role=form.elements.processingRole.value,total=files.reduce((sum,file)=>sum+file.size,0),progress=form.querySelector('progress');if(!files.length||files.length>128||files.some(file=>file.size>64*1024**2)||total>256*1024**2)return toast('Browser upload limit exceeded (128 files, 64 MB each, 256 MB total); use the server import folder for larger artifacts',true);state.busy=true;try{let preparedCount=0;const prepared=[];for(let index=0;index<files.length;index++){const buffer=await files[index].arrayBuffer();prepared.push({file:files[index],spec:{id:`file-${index}`,relativePath:files[index].webkitRelativePath||files[index].name,byteSize:files[index].size,sha256:await digest(buffer),contentType:files[index].type||'application/octet-stream',processingRole:role}});progress.value=Math.round(++preparedCount/files.length*15)}const created=await api(`/api/v1/datasets/${encodeURIComponent(datasetId)}/uploads`,{method:'POST',body:{files:prepared.map(item=>item.spec)}}),upload=created.upload,token=created.uploadToken;sessionStorage.setItem('ltds-viewer-upload',JSON.stringify({datasetId,uploadId:upload.id,manifest:prepared.map(item=>item.spec)}));let sent=0;for(const item of prepared){const remote=upload.files.find(file=>file.id===item.spec.id),missing=new Set(remote.missingChunks);for(let index=0;index<remote.chunkCount;index++){const start=index*upload.chunkSize,end=Math.min(start+upload.chunkSize,item.file.size);if(missing.has(index)){const chunk=await item.file.slice(start,end).arrayBuffer(),response=await fetch(`/api/v1/admin/uploads/${encodeURIComponent(upload.id)}/files/${encodeURIComponent(item.spec.id)}/chunks/${index}`,{method:'PUT',headers:{Authorization:`Bearer ${state.token}`,'Content-Type':'application/octet-stream','X-Upload-Token':token,'X-Chunk-SHA256':await digest(chunk)},body:chunk});if(!response.ok)throw Error(`Chunk upload failed (${response.status})`)}sent+=end-start;progress.value=15+Math.round(sent/Math.max(total,1)*80)}}await api(`/api/v1/admin/uploads/${encodeURIComponent(upload.id)}/finalize`,{method:'POST',body:{uploadToken:token}});sessionStorage.removeItem('ltds-viewer-upload');progress.value=100;modal.close();toast('Upload finalized; processing will index the dataset');await load()}catch(error){toast(`${error.message}. Reselect the same files to resume.`,true)}finally{state.busy=false}}

async function pagedApi(path,key){const items=[],seen=new Set();let cursor=null;do{const separator=path.includes('?')?'&':'?',page=await api(`${path}${separator}limit=100${cursor?`&cursor=${encodeURIComponent(cursor)}`:''}`);items.push(...(page[key]||[]));cursor=page.nextCursor||null;if(cursor&&seen.has(cursor))throw Error(`Pagination cursor repeated for ${key}`);if(cursor)seen.add(cursor)}while(cursor);return{[key]:items}}
async function pagedStorage(){let first=null,cursor=null;const items=[],seen=new Set();do{const page=await api(`/api/v1/storage?limit=100${cursor?`&cursor=${encodeURIComponent(cursor)}`:''}`);if(!first)first=page;items.push(...(page.trash?.items||[]));cursor=page.trash?.nextCursor||null;if(cursor&&seen.has(cursor))throw Error('Pagination cursor repeated for trash');if(cursor)seen.add(cursor)}while(cursor);return{...(first||{}),trash:{...(first?.trash||{}),items,nextCursor:null}}}
async function load(){const requests=[pagedApi('/api/v1/projects','projects'),pagedApi('/api/v1/datasets','datasets'),pagedApi('/api/v1/tasks','tasks'),api('/api/v1/processing/providers?limit=100'),api('/api/v1/processing/presets'),pagedApi('/api/v1/processing/outputs','outputs'),pagedStorage(),can('viewer.storage.purge')?pagedApi('/api/v1/storage/mutations?status=failed','mutations'):Promise.resolve({mutations:[]}),api('/api/v1/processing/ready'),api('/api/v1/workspace/client-grants')],results=await Promise.allSettled(requests);if(!state.token)return access();[state.projects,state.datasets,state.tasks,state.providers,state.presets,state.outputs,state.storage,state.failedMutations,state.ready,state.clientAccess]=[results[0].value?.projects||[],results[1].value?.datasets||[],results[2].value?.tasks||[],results[3].value?.providers||[],results[4].value?.presets||[],results[5].value?.outputs||[],results[6].value||null,results[7].value?.mutations||[],results[8].value||null,results[9].value||null];if(state.selectedProjectId&&!state.projects.some(project=>project.id===state.selectedProjectId))state.selectedProjectId=null;const published=state.outputs.filter(output=>output.activePublished),shareResults=await Promise.allSettled(published.map(output=>api(`/api/v1/processing/outputs/${encodeURIComponent(output.id)}/shares`)));state.shares=Object.fromEntries(published.map((output,index)=>[output.id,shareResults[index].value?.shares||[]]));const okay=state.ready?.ok===true;document.querySelector('#nav-health-dot').className=`health-dot ${okay?'good':'bad'}`;document.querySelector('#nav-health-label').textContent=okay?'Platform ready':'Attention needed';render()}
function access(){content.innerHTML='<div class="auth-state"><div><p class="eyebrow">Secure workspace</p><h2>Open Viewer from LTDS Operations</h2><p>This workspace reuses your Operations identity and has no separate login.</p></div></div>'}

document.querySelector('#nav-toggle').onclick=()=>shell.classList.toggle('nav-open');
document.querySelector('#refresh-button').onclick=()=>state.token?load():access();
document.querySelector('#new-project-button').onclick=newProjectModal;
try{const redeemed=await redeemGrant();if(!redeemed&&state.token)await restoreWorkspaceSession();if(state.token)await load();else{renderNav();access()}}catch(error){if(error.status===401||!state.token)clearWorkspaceAuthorization();else{try{if(!workspaceRenewal)await restoreWorkspaceSession()}catch(currentError){if(currentError.status===401)clearWorkspaceAuthorization()}if(state.token){renderNav();toast('Viewer session renewal is temporarily unavailable; your current session was preserved',true);await load()}}}
